     8→
     9→export interface TokenBudgetConfig {
    10→  /** Total token budget for this run */
    11→  budget: number;
    12→  /**
    13→   * Called when usage crosses 50% or 80% of budget.
    14→   * Receives the threshold label, current token count, and total budget.
    15→   * Returning from this callback continues execution.
    16→   */
    17→  onWarning: (threshold: '50%' | '80%', currentCount: number, budget: number) => void;
    18→}
    19→
    20→export interface TokenBudgetHandle {
    21→  /** The composable middleware to insert into the stack */
    22→  middleware: Middleware;
    23→  /** Returns the total tokens consumed so far — for teardown reporting */
    24→  getTokenCount: () => number;
    25→}
    26→
    27→/**
    28→ * Factory that creates a token budget middleware for a single run.
    29→ *
    30→ * Each call to `createTokenBudget` produces an isolated closure — no cross-run
    31→ * state. The returned `middleware` conforms to the `Middleware` type and wraps
    32→ * any `LlmCallFn` without requiring changes to agent internals.
    33→ *
    34→ * Warning callbacks fire at most once each:
    35→ *   - `onWarning('50%', ...)` fires the first time cumulative usage >= 50 % of budget
    36→ *   - `onWarning('80%', ...)` fires the first time cumulative usage >= 80 % of budget
    37→ *
    38→ * When cumulative usage reaches or exceeds 100 % of budget, `BudgetExceededError`
    39→ * is thrown on that call's return — the overshoot is intentional (see spec edge cases).
    40→ */
    41→export function createTokenBudget(config: TokenBudgetConfig): TokenBudgetHandle {
    42→  const { budget, onWarning } = config;
    43→
    44→  // Per-run state — scoped entirely to this closure
    45→  let tokenCount = 0;
    46→  let warned50 = false;
    47→  let warned80 = false;
    48→
    49→  const middleware: Middleware = (next: LlmCallFn): LlmCallFn => {
    50→    return async (messages: LlmMessage[], options?: LlmCallOptions) => {
    51→      const response = await next(messages, options);
    52→
    53→      // Accumulate usage from the response
    54→      tokenCount += response.usage.promptTokens + response.usage.completionTokens;
    55→
    56→      const usageRatio = tokenCount / budget;
    57→
    58→      // 50% warning — fires at most once
    59→      if (!warned50 && usageRatio >= 0.5) {
    60→        warned50 = true;
    61→        onWarning('50%', tokenCount, budget);
    62→      }
    63→
    64→      // 80% warning — fires at most once
    65→      if (!warned80 && usageRatio >= 0.8) {
    66→        warned80 = true;
    67→        onWarning('80%', tokenCount, budget);
    68→      }
    69→
    70→      // Hard kill at 100%
    71→      if (usageRatio >= 1.0) {
    72→        throw new BudgetExceededError(tokenCount, budget);
    73→      }
    74→
    75→      return response;
    76→    };
    77→  };
    78→
    79→  return {
    80→    middleware,
    81→    getTokenCount: () => tokenCount,
    82→  };
    83→}
    84→"}]}

